76	 */
77	
78	@RestController
79	@CrossOrigin(exposedHeaders = "errors, content-type")
80	@RequestMapping("/api")
81	public class OwnerRestControllerV1 implements OwnersApi {
82	
83	    /**
84	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
85	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
86	     */
87	    private static final Pattern EMAIL_PATTERN =
88	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
89	
90	    /**
91	     * Email domains rejected as disposable/throwaway addresses. An owner whose email domain matches
92	     * one of these (compared case-insensitively) is rejected with 400.
93	     */
94	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
95	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
96	
97	    /**
98	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
99	     * new owner's id, customerCode, registrationDate, membershipLevel and membershipNumber, followed
100	     * by an immutable structured {@link OwnerCreatedEvent} serialized as JSON.
101	     */
102	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
103	
104	    /**
105	     * Source of the {@code seq} carried by each {@link OwnerCreatedEvent}: a monotonically increasing
106	     * integer allocated once per successful owner create, so the structured events form an ordered,
107	     * gap-free sequence within the running application.
108	     */
109	    private static final AtomicLong AUDIT_EVENT_SEQUENCE = new AtomicLong();
110	
111	    /**
112	     * Common street-type abbreviations expanded during address normalization, keyed by the
113	     * upper-cased abbreviation.
114	     */
115	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
116	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
117	
118	    /**
119	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
120	     * city already holds this many owners.
121	     */
122	    private static final int CITY_CAPACITY = 50;
123	
124	    /**
125	     * Maximum number of owners that may be created on a single day. A create is rejected once this
126	     * many owners already carry the current day as their {@code registrationDate}.
127	     */
128	    private static final int DAILY_OWNER_LIMIT = 100;
129	
130	    /**
131	     * Fixed public holidays that the business-day roll skips: when an adjusted registration date lands
132	     * on one of these it advances to the next non-holiday business day.
133	     */
134	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
135	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
136	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
137	
138	    private final ClinicService clinicService;
139	
140	    private final OwnerMapper ownerMapper;
141	
142	    private final PetMapper petMapper;
143	
144	    private final VisitMapper visitMapper;
145	
146	    /**
147	     * Remembers the id of the owner created under each seen {@code Idempotency-Key}, so a create that
148	     * repeats with an already-seen key returns the originally created owner instead of creating a
149	     * duplicate.
150	     */
151	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
152	
153	    public OwnerRestControllerV1(ClinicService clinicService,
154	                                 OwnerMapper ownerMapper,
155	                                 PetMapper petMapper,
156	                                 VisitMapper visitMapper) {
157	        this.clinicService = clinicService;
158	        this.ownerMapper = ownerMapper;
159	        this.petMapper = petMapper;
160	        this.visitMapper = visitMapper;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
166	        Collection<Owner> owners;
167	        if (lastName != null) {
168	            owners = this.clinicService.findOwnerByLastName(lastName);
169	        } else {
170	            owners = this.clinicService.findAllOwners();
171	        }
172	        if (owners.isEmpty()) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
191	        String idempotencyKey = currentIdempotencyKey();
192	        if (idempotencyKey != null) {
193	            Integer existingId = ownersByIdempotencyKey.get(idempotencyKey);
194	            if (existingId != null) {
195	                Owner existing = this.clinicService.findOwnerById(existingId);
196	                if (existing != null) {
197	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
198	                }
199	            }
200	        }
201	        validateRequiredFields(ownerFieldsDto);
202	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
203	        HttpHeaders headers = new HttpHeaders();
204	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
205	        applyAddress(owner, ownerFieldsDto);
206	        rejectFutureRegistrationDate(owner.getRegistrationDate());
207	        LocalDate effectiveDate = owner.getRegistrationDate() == null
208	            ? LocalDate.now()
209	            : owner.getRegistrationDate();
210	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
211	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
212	        rejectWhenCityAtCapacity(owner.getCity());
213	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
214	        applyHousehold(owner);
215	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
216	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
217	        rejectDuplicateIdentity(owner);
218	        owner.setCustomerCode(customerCode(owner));
219	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
220	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
221	        flagPossibleDuplicate(owner, sharesHousehold);
222	        this.clinicService.saveOwner(owner);
223	        if (idempotencyKey != null) {
224	            ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
225	        }
226	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
227	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
228	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
229	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
230	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
231	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
232	        AUDIT.info("{}", event.toJson());
233	        headers.setLocation(UriComponentsBuilder.newInstance()
234	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
235	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
236	    }
237	
238	    /**
239	     * Reads the {@code Idempotency-Key} header of the request currently being handled, returning
240	     * {@code null} when the header is absent or blank (or there is no bound request). A non-blank
241	     * value opts the create into idempotent replay via {@link #ownersByIdempotencyKey}.
242	     *
243	     * @return the trimmed idempotency key, or {@code null} when none was supplied
244	     */
245	    private String currentIdempotencyKey() {
246	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
247	            return null;
248	        }
249	        String key = attrs.getRequest().getHeader("Idempotency-Key");
250	        return isBlank(key) ? null : key.trim();
251	    }
252	
253	    /**
254	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
255	     * code derived from the owner's postcode (falling back to the city-to-region table, then
256	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
257	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}).
258	     *
259	     * <p>Should the computed code collide with an existing owner's {@code customerCode}, it is
260	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
261	     * unique (e.g. {@code NSW-1A2B3C4D-2}), so distinct owners always receive distinct customer codes.
262	     *
263	     * @param owner the owner being created, with its normalized telephone already applied
264	     * @return the assigned, de-duplicated customer code
265	     */
266	    /**
267	     * Returns the owner's current primary identifier, the value carried by the {@link OwnerCreatedEvent}
268	     * so downstream consumers can key the create off the owner's canonical identity. Today an owner's
269	     * primary identifier is its {@code customerCode}; when the customer code is later unified into the
270	     * member id this method returns the member id instead, and the emitted event follows automatically.
271	     *
272	     * @param owner the freshly created owner, with its identifiers already assigned
273	     * @return the owner's current primary identifier
274	     */
275	    private String primaryIdentifier(Owner owner) {
276	        return owner.getCustomerCode();
277	    }
278	
279	    private String customerCode(Owner owner) {
280	        String base = regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
281	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
282	            .map(Owner::getCustomerCode)
283	            .filter(code -> code != null)
284	            .collect(java.util.stream.Collectors.toSet());
285	        if (!existingCodes.contains(base)) {
286	            return base;
287	        }
288	        int n = 2;
289	        while (existingCodes.contains(base + "-" + n)) {
290	            n++;
291	        }
292	        return base + "-" + n;
293	    }
294	
295	    /**
296	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
297	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
298	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
299	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
300	     * postcode nor the city identifies a region.
301	     *
302	     * @param owner the owner being created
303	     * @return the derived region code, never {@code null}
304	     */
305	    private String regionCode(Owner owner) {
306	        String fromPostcode = regionFromPostcode(owner.getPostcode());
307	        if (fromPostcode != null) {
308	            return fromPostcode;
309	        }
310	        String fromCity = region(owner.getCity());
311	        return fromCity == null ? "UNKNOWN" : fromCity;
312	    }
313	
314	    /**
315	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
316	     * postcode is absent, not 4 digits, or in no known range.
317	     *
318	     * @param postcode the owner's postcode, may be {@code null}
319	     * @return the region code, or {@code null} when no known range contains the postcode
320	     */
321	    private String regionFromPostcode(String postcode) {
322	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
323	            return null;
324	        }
325	        int value = Integer.parseInt(postcode);
326	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
327	            int[] range = entry.getValue();
328	            if (value >= range[0] && value <= range[1]) {
329	                return entry.getKey();
330	            }
331	        }
332	        return null;
333	    }
334	
335	    /**
336	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
337	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
338	     *
339	     * @param telephone the owner's normalized (E.164) telephone
340	     * @param lastName  the owner's last name
341	     * @return the 8-character upper-cased hex hash
342	     */
343	    private String identityHash8(String telephone, String lastName) {
344	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
345	        try {
346	            byte[] digest = MessageDigest.getInstance("SHA-256")
347	                .digest(input.getBytes(StandardCharsets.UTF_8));
348	            StringBuilder hex = new StringBuilder(digest.length * 2);
349	            for (byte b : digest) {
350	                hex.append(String.format("%02x", b));
351	            }
352	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
353	        } catch (NoSuchAlgorithmException ex) {
354	            throw new IllegalStateException("SHA-256 not available", ex);
355	        }
356	    }
357	
358	    /**
359	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
360	     * last two digits of the fiscal year of the owner's business-day-adjusted registration date,
361	     * zero-padded (e.g. {@code NSW-1A2B3C4D-M26}). The fiscal year starts on 1 July.
362	     *
363	     * @param customerCode     the owner's assigned customer code
364	     * @param registrationDate the owner's business-day-adjusted registration date
365	     * @return the assigned membership number
366	     */
367	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
368	        return String.format("%s-M%02d", customerCode, fiscalYear(registrationDate) % 100);
369	    }
370	
371	    /**
372	     * The month the fiscal year starts on (1 July).
373	     */
374	    private static final int FISCAL_YEAR_START_MONTH = 7;
375	
376	    /**
377	     * Derives the fiscal year of the given date. The fiscal year starts on 1 July, so a date on or
378	     * after 1 July belongs to the following calendar year's fiscal year (e.g. 2026-07-01 is fiscal
379	     * year 2027) while an earlier date takes the calendar year unchanged.
380	     *
381	     * @param date the date to derive the fiscal year of
382	     * @return the fiscal year
383	     */
384	    private int fiscalYear(LocalDate date) {
385	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
386	    }
387	
388	    /**
389	     * Counts the existing owners that already share the given firstName and lastName, compared
390	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
391	     * the owners that pre-existed this create.
392	     *
393	     * @param firstName the new owner's first name
394	     * @param lastName  the new owner's last name
395	     * @return the number of existing namesakes
396	     */
397	    private int countNamesakes(String firstName, String lastName) {
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
400	                && equalsIgnoreCase(existing.getLastName(), lastName))
401	            .count();
402	    }
403	
404	    /**
405	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
406	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
407	     * still resemble an existing owner: when it shares an existing owner's {@code soundex(lastName)}
408	     * and postcode while deriving a different identityKey, the owner is flagged with
409	     * {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing owner's id.
410	     * When no such owner exists the flag is set to {@code false} and no match id is recorded. An
411	     * owner with no postcode can never soft-match and is always {@code false}.
412	     *
413	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
414	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
415	     * always flagged {@code false}.
416	     *
417	     * @param owner           the owner being created, with its normalized telephone already applied
418	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
419	     *                        never flagged as a possible duplicate
420	     */
421	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
422	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
423	        if (match != null) {
424	            owner.setPossibleDuplicate(true);
425	            owner.setPossibleDuplicateOf(match.getId());
426	        } else {
427	            owner.setPossibleDuplicate(false);
428	            owner.setPossibleDuplicateOf(null);
429	        }
430	    }
431	
432	    /**
433	     * Finds the existing owner this owner soft-matches: a different {@link #identityKey(Owner)
434	     * identityKey} but the same {@code soundex(lastName)} and the same postcode. Because the
435	     * telephone now feeds the identityKey, two owners sharing a lastName and postcode with different
436	     * telephones have different keys and so soft-match here rather than being rejected as a hard
437	     * duplicate. When several existing owners match, the one with the lowest id is chosen so the
438	     * result is deterministic. Returns {@code null} when the owner has no postcode or no such
439	     * existing owner exists.
440	     *
441	     * @param owner the owner being created
442	     * @return the matching existing owner, or {@code null} when there is no soft-match
443	     */
444	    private Owner findPossibleDuplicate(Owner owner) {
445	        if (isBlank(owner.getPostcode())) {
446	            return null;
447	        }
448	        String identityKey = identityKey(owner);
449	        String soundex = IdentityKeys.soundex(owner.getLastName());
450	        return this.clinicService.findAllOwners().stream()
451	            .filter(existing -> !identityKey.equals(identityKey(existing))
452	                && soundex.equals(IdentityKeys.soundex(existing.getLastName()))
453	                && owner.getPostcode().equals(existing.getPostcode()))
454	            .min(Comparator.comparing(Owner::getId))
455	            .orElse(null);
456	    }
457	
458	    /**
459	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
460	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
461	     * customer-code sequence is derived.
462	     *
463	     * @param city the new owner's city
464	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
465	     */
466	    private void rejectWhenCityAtCapacity(String city) {
467	        long count = this.clinicService.findAllOwners().stream()
468	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
469	            .count();
470	        if (count >= CITY_CAPACITY) {
471	            throw new CityAtCapacityException(city);
472	        }
473	    }
474	
475	    /**
