508	    /**
509	     * Rolls a registration date forward onto a business day: while it falls on a Saturday, a Sunday or
510	     * a listed {@link #PUBLIC_HOLIDAYS public holiday} it advances one day at a time until it lands on
511	     * a non-holiday weekday, otherwise it is returned unchanged. Applied to the effective registration
512	     * date (whether supplied in the request or defaulted to the server date) so a weekend or holiday
513	     * value never persists as an owner's {@code registrationDate}.
514	     *
515	     * @param date the effective registration date
516	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
517	     */
518	    private LocalDate toBusinessDay(LocalDate date) {
519	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
520	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
521	            || PUBLIC_HOLIDAYS.contains(date)) {
522	            date = date.plusDays(1);
523	        }
524	        return date;
525	    }
