583	    /**
584	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
585	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
586	     */
587	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
588	        "NSW", new int[] {2000, 2099},
589	        "VIC", new int[] {3000, 3099},
590	        "QLD", new int[] {4000, 4099});
