592	    /**
593	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
594	     * is optional and accepted, keeping the create contract backward-compatible. When present the
595	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
596	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
597	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
598	     *
599	     * @param postcode the raw postcode value as submitted, may be {@code null}
600	     * @param city     the owner's city, used to resolve the region whose range applies
601	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
602	     *                                  the city's region
603	     */
604	    private void validatePostcode(String postcode, String city) {
605	        if (isBlank(postcode)) {
606	            return;
607	        }
608	        if (!postcode.matches("[0-9]{4}")) {
609	            throw new InvalidPostcodeException(postcode, city);
610	        }
611	        String region = region(city);
612	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
613	        if (range != null) {
614	            int value = Integer.parseInt(postcode);
615	            if (value < range[0] || value > range[1]) {
616	                throw new InvalidPostcodeException(postcode, city);
617	            }
618	        }
619	    }
