621	    /**
622	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
623	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
624	     *
625	     * @param city the owner's city
626	     * @return the region code, or {@code null} when the city has no known region
627	     */
628	    private String region(String city) {
629	        if (city == null) {
630	            return null;
631	        }
632	        return switch (city) {
633	            case "Sydney" -> "NSW";
634	            case "Melbourne" -> "VIC";
635	            case "Brisbane" -> "QLD";
636	            default -> null;
637	        };
638	    }
