640	    /**
641	     * The number of national (subscriber) digits an E.164 number must carry for a given country
642	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
643	     * national digits and the North American Numbering Plan ('+1') requires 10.
644	     */
645	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
646	        Map.of("61", 9, "1", 10);
647	
648	    /**
649	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
650	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
651	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
652	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
653	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
654	     *
655	     * @param telephone the raw telephone value as submitted
656	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
657	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
658	     *                                   national-number length is wrong for its country code
659	     */
660	    private String normalizeTelephone(String telephone) {
661	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
662	        String nationalSignificantNumber;
663	        if (cleaned.startsWith("+")) {
664	            nationalSignificantNumber = cleaned.substring(1);
665	        } else {
666	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
667	            nationalSignificantNumber = "61" + national;
668	        }
669	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
670	            throw new InvalidTelephoneException(telephone);
671	        }
672	        validateNationalNumberLength(nationalSignificantNumber, telephone);
673	        return "+" + nationalSignificantNumber;
674	    }
675	
676	    /**
677	     * Validates the national-number length of an E.164 number against its country calling code. The
678	     * significant number is a country code immediately followed by the national digits; for each
679	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
680	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
681	     * left unchecked.
682	     *
683	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
684	     * @param rejectedValue             the raw telephone value, reported on rejection
685	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
686	     */
687	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
688	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
689	            String countryCode = rule.getKey();
690	            if (nationalSignificantNumber.startsWith(countryCode)) {
691	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
692	                if (nationalDigits != rule.getValue()) {
693	                    throw new InvalidTelephoneException(rejectedValue);
694	                }
695	                return;
696	            }
697	        }
698	    }
