700	    /**
701	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
702	     * value is treated as absent and returns {@code null}); when present the value must be a
703	     * syntactically valid address, and is stored and returned lower-cased.
704	     *
705	     * @param email the raw email value as submitted, may be {@code null}
706	     * @return the lower-cased email, or {@code null} when none was supplied
707	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
708	     */
709	    private String normalizeEmail(String email) {
710	        if (email == null || email.isBlank()) {
711	            return null;
