724	    /**
725	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
726	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing, non-deleted owner.
727	     * Because the key is the SHA-256 of the normalized telephone, lower-cased email and
728	     * {@code soundex(lastName)} joined together, this one check is the sole duplicate rule: only an
729	     * exact full-key match counts as a duplicate, so two owners sharing a lastName and postcode but
730	     * carrying different telephones have different keys and are both allowed (the second is instead
731	     * flagged a soft match).
732	     *
733	     * @param owner the owner being created, with its normalized telephone and email already applied
734	     * @throws DuplicateIdentityException if another owner already has the same identityKey
735	     */
736	    private void rejectDuplicateIdentity(Owner owner) {
737	        String identityKey = identityKey(owner);
738	        boolean inUse = this.clinicService.findAllOwners().stream()
739	            .filter(existing -> !isDeleted(existing))
740	            .map(this::identityKey)
741	            .anyMatch(identityKey::equals);
742	        if (inUse) {
743	            throw new DuplicateIdentityException(identityKey);
744	        }
745	    }
