747	    /**
748	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 of
749	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A {@code null}
750	     * telephone or email contributes an empty segment. Every duplicate decision is made by comparing
751	     * whole identityKeys.
752	     *
753	     * @param owner the owner whose identityKey to derive
754	     * @return the derived identityKey
755	     */
756	    private String identityKey(Owner owner) {
757	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
