760	    /**
761	     * Applies the household rule to an owner being created. The household is keyed on
762	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
763	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
764	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
765	     *
766	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
767	     * same householdId is a member of the same household. A new owner sharing an existing household
768	     * is admitted as a further member of it — its membership level is then capped by the household
769	     * (see {@code OwnerMapper#membershipLevel}) rather than the create being rejected.
770	     *
771	     * @param owner the owner being created
772	     */
773	    private void applyHousehold(Owner owner) {
774	        owner.setHouseholdId(householdId(owner));
775	    }
