777	    /**
778	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
779	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
780	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
781	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
782	     * creation order. A {@code null} postcode contributes an empty segment.
783	     *
784	     * @param owner the owner whose household identifier to derive
785	     * @return the household identifier
786	     */
787	    private String householdId(Owner owner) {
788	        String lastNameKey = toHouseholdKey(owner.getLastName());
789	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
790	        try {
791	            byte[] digest = MessageDigest.getInstance("SHA-256")
792	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
793	            StringBuilder hex = new StringBuilder(digest.length * 2);
794	            for (byte b : digest) {
795	                hex.append(String.format("%02x", b));
796	            }
797	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
798	        } catch (NoSuchAlgorithmException ex) {
799	            throw new IllegalStateException("SHA-256 not available", ex);
800	        }
801	    }
