803	    /**
804	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
805	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
806	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
807	     * string.
808	     */
809	    private String toHouseholdKey(String value) {
810	        if (value == null) {
811	            return "";
812	        }
813	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
814	    }
