816	    /**
817	     * Applies the owner's address, preferring the structured form over the flat one. The structured
818	     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
819	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
820	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
821	     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
822	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
823	     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
824	     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
825	     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
826	     * address therefore sees the structured value when present, falling back to the flat one.
827	     *
828	     * @param owner the owner being created
829	     * @param dto   the submitted owner fields
830	     */
831	    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
832	        String line1 = normalizeAddress(dto.getAddressLine1());
833	        String line2 = normalizeAddress(dto.getAddressLine2());
834	        String flat = normalizeAddress(dto.getAddress());
835	        String effectiveLine1 = line1.isEmpty() ? flat : line1;
836	        String effectiveLine2 = line1.isEmpty() ? "" : line2;
837	        String composed = effectiveLine2.isEmpty()
838	            ? effectiveLine1
839	            : effectiveLine1 + " " + effectiveLine2;
840	        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
841	        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
842	        owner.setAddress(composed);
843	    }
