845	    /**
846	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
847	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
848	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
849	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
850	     * value, or one that is blank once trimmed, normalizes to an empty string.
851	     *
852	     * @param address the raw address value as submitted, may be {@code null}
853	     * @return the normalized address, or an empty string when none was supplied
854	     */
855	    private String normalizeAddress(String address) {
856	        if (address == null) {
857	            return "";
858	        }
859	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
860	        if (collapsed.isEmpty()) {
861	            return "";
862	        }
863	        String[] tokens = collapsed.split(" ");
864	        StringBuilder normalized = new StringBuilder(collapsed.length());
865	        for (int i = 0; i < tokens.length; i++) {
866	            if (i > 0) {
867	                normalized.append(' ');
868	            }
869	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
870	        }
871	        return normalized.toString();
872	    }
