969	    /**
970	     * Immutable structured audit event emitted alongside the human-readable audit line on a successful
971	     * owner create. It records the create's monotonic {@code seq}, the new owner's id, the owner's
972	     * current primary identifier and its membership level, plus a fixed {@code OWNER_CREATED} marker.
973	     *
974	     * <p>The primary identifier is serialized under the {@code customerCode} key, matching the owner's
975	     * present-day primary identifier. When the customer code is later unified into the member id the
976	     * event simply carries the member id value in its place.
977	     */
978	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
979	                                     Integer membershipLevel) {
980	
981	        private static final String EVENT = "OWNER_CREATED";
982	
983	        /**
984	         * Renders the event as a compact JSON object
985	         * {@code {"seq":..,"ownerId":..,"customerCode":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
986	         */
987	        String toJson() {
988	            StringBuilder json = new StringBuilder(96);
989	            json.append('{')
990	                .append("\"seq\":").append(this.seq)
991	                .append(",\"ownerId\":").append(this.ownerId)
992	                .append(",\"customerCode\":").append(jsonString(this.customerCode))
993	                .append(",\"membershipLevel\":").append(this.membershipLevel)
994	                .append(",\"event\":").append(jsonString(EVENT))
995	                .append('}');
996	            return json.toString();
997	        }
998	
999	        /**
1000	         * Renders a nullable string as a JSON literal: {@code null} when absent, otherwise a
1001	         * double-quoted, minimally-escaped string.
1002	         */
1003	        private static String jsonString(String value) {
1004	            if (value == null) {
1005	                return "null";
1006	            }
1007	            StringBuilder out = new StringBuilder(value.length() + 2);
1008	            out.append('"');
1009	            for (int i = 0; i < value.length(); i++) {
1010	                char c = value.charAt(i);
1011	                switch (c) {
1012	                    case '"' -> out.append("\\\"");
1013	                    case '\\' -> out.append("\\\\");
1014	                    case '\n' -> out.append("\\n");
1015	                    case '\r' -> out.append("\\r");
1016	                    case '\t' -> out.append("\\t");
1017	                    default -> {
1018	                        if (c < 0x20) {
1019	                            out.append(String.format("\\u%04x", (int) c));
1020	                        } else {
1021	                            out.append(c);
1022	                        }
1023	                    }
1024	                }
1025	            }
1026	            out.append('"');
1027	            return out.toString();
1028	        }
1029	    }
