128	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
129	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
130	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
131	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
132	     */
133	    protected String telephoneDisplay(Owner owner) {
134	        String telephone = owner.getTelephone();
135	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
136	            return telephone;
137	        }
138	        String digits = telephone.substring(1);
139	        String countryCode = KNOWN_COUNTRY_CODES.stream()
140	            .filter(digits::startsWith)
141	            .findFirst()
142	            .orElse("");
143	        String national = digits.substring(countryCode.length());
144	        StringBuilder grouped = new StringBuilder();
145	        for (int i = 0; i < national.length(); i++) {
146	            if (i > 0 && i % 3 == 0) {
147	                grouped.append(' ');
148	            }
149	            grouped.append(national.charAt(i));
150	        }
151	        return "+" + countryCode + " " + grouped;
152	    }
153	
154	    /**
155	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key: the
156	     * lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
157	     * soundex(lastName)}. A {@code null} telephone or email contributes an empty segment.
158	     */
159	    protected String identityKey(Owner owner) {
160	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
161	    }
162	
163	    /**
164	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
165	     * present, otherwise {@code PHONE}.
166	     */
167	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
168	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
169	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
170	    }
171	
172	    /**
173	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
174	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
175	     */
176	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
177	        "NSW", new int[] {2000, 2099},
178	        "VIC", new int[] {3000, 3099},
179	        "QLD", new int[] {4000, 4099});
180	
181	    /**
182	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
183	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
184	     * moves in lockstep with the identity assigned on create. When no customer code has been
185	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
186	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
187	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
188	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
189	     */
190	    protected String locality(Owner owner) {
191	        String customerCode = owner.getCustomerCode();
192	        if (customerCode != null) {
193	            int dash = customerCode.indexOf('-');
194	            if (dash > 0) {
195	                return customerCode.substring(0, dash);
196	            }
197	        }
198	        String fromPostcode = regionFromPostcode(owner.getPostcode());
199	        if (fromPostcode != null) {
200	            return fromPostcode;
201	        }
202	        String city = owner.getCity();
203	        if (city == null) {
204	            return "UNKNOWN";
205	        }
206	        return switch (city) {
207	            case "Sydney" -> "NSW";
208	            case "Melbourne" -> "VIC";
209	            case "Brisbane" -> "QLD";
210	            default -> "UNKNOWN";
211	        };
212	    }
213	
214	    /**
215	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
216	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
217	     */
218	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
219	        "NSW", "Australia/Sydney",
220	        "VIC", "Australia/Melbourne",
221	        "QLD", "Australia/Brisbane");
222	
223	    /**
224	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
225	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
226	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
227	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
228	     */
229	    protected String timezone(Owner owner) {
230	        return REGION_TIMEZONE.get(locality(owner));
231	    }
232	
233	    /**
234	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
235	     * the postcode is absent, not 4 digits, or in no known range.
236	     */
237	    private String regionFromPostcode(String postcode) {
238	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
239	            return null;
240	        }
241	        int value = Integer.parseInt(postcode);
242	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
243	            int[] range = entry.getValue();
244	            if (value >= range[0] && value <= range[1]) {
245	                return entry.getKey();
246	            }
247	        }
248	        return null;
249	    }
250	
251	    /**
252	     * The minimum {@link #membershipLevel(Owner) membership level} at which an owner is a
253	     * {@code PREMIUM} tier for {@link #ownerSegment(Owner) segmentation}; below it the owner is
254	     * {@code STANDARD}.
255	     */
256	    private static final int PREMIUM_TIER_MIN_LEVEL = 3;
257	
258	    /**
259	     * The regions treated as {@code METRO} for {@link #ownerSegment(Owner) segmentation}; any other
260	     * locality (e.g. {@code UNKNOWN}) is {@code REGIONAL}.
261	     */
262	    private static final java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
263	
264	    /**
265	     * Derives the owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} (one of
266	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
267	     * {@code STANDARD_REGIONAL}). TIER is {@code PREMIUM} when the owner's
268	     * {@link #membershipLevel(Owner) membership level} is {@value #PREMIUM_TIER_MIN_LEVEL} or more,
269	     * otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
270	     * {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
271	     * {@code REGIONAL}.
272	     */
273	    protected OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
274	        String tier = membershipLevel(owner) >= PREMIUM_TIER_MIN_LEVEL ? "PREMIUM" : "STANDARD";
275	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
276	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
277	    }
278	
279	    /**
280	     * The minimum household size (counting the owner itself) that earns household membership
281	     * points.
282	     */
283	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
284	
285	    /**
286	     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
287	     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
288	     * clears this threshold.
289	     */
290	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
291	
292	    /**
293	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
294	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
295	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
296	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
297	     */
298	    protected Integer membershipPoints(Owner owner) {
299	        int points = 0;
300	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
301	        if (hasEmail) {
302	            points += 2;
303	        }
304	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
305	        if (noNamesakes) {
306	            points += 1;
307	        }
308	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
309	            points += 2;
310	        }
311	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
312	            points += 3;
313	        }
314	        return points;
315	    }
316	
317	    /**
318	     * Derives the owner's membership level, capped by their household. The level starts from the
319	     * owner's own {@link #uncappedMembershipLevel(Owner) points-based level} but may not exceed one
320	     * above the current maximum level among the owner's existing household members (other owners
321	     * sharing its {@code householdId}). When the owner has no existing household member no cap
322	     * applies and the points-based level is returned unchanged.
323	     */
324	    protected Integer membershipLevel(Owner owner) {
325	        int level = uncappedMembershipLevel(owner);
326	        OptionalInt maxHouseholdLevel = otherHouseholdMembers(owner)
327	            .mapToInt(this::uncappedMembershipLevel)
328	            .max();
329	        if (maxHouseholdLevel.isEmpty()) {
330	            return level;
331	        }
332	        return Math.min(level, maxHouseholdLevel.getAsInt() + 1);
333	    }
334	
335	    /**
336	     * The owner's points-based membership level, before the household ceiling is applied: level 1
337	     * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more (see
338	     * {@link #membershipPoints(Owner) membership points}). The household members' maximum against
339	     * which {@link #membershipLevel(Owner)} caps is measured with this uncapped value, so mutual
340	     * household members do not recurse into each other's caps.
341	     */
342	    private int uncappedMembershipLevel(Owner owner) {
343	        int points = membershipPoints(owner);
344	        if (points <= 1) {
345	            return 1;
346	        }
347	        if (points <= 3) {
348	            return 2;
349	        }
350	        if (points <= 5) {
351	            return 3;
352	        }
353	        return 4;
354	    }
355	
356	    /**
357	     * The owner's existing household members: every other owner (excluding the owner itself) sharing
358	     * its {@code householdId}. Empty when the owner has no household identifier or is the sole member
359	     * of its household.
360	     */
361	    private Stream<Owner> otherHouseholdMembers(Owner owner) {
362	        String householdId = owner.getHouseholdId();
363	        if (householdId == null) {
364	            return Stream.empty();
365	        }
366	        return this.clinicService.findAllOwners().stream()
367	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
368	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()));
369	    }
370	
371	    /**
372	     * The number of owners in this owner's household — the count of owners (including this one)
373	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
374	     */
375	    private long householdSize(Owner owner) {
376	        String householdId = owner.getHouseholdId();
377	        if (householdId == null) {
378	            return 0;
379	        }
380	        return this.clinicService.findAllOwners().stream()
381	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
382	            .count();
383	    }
384	
385	    /**
386	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
387	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
388	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
389	     * owner without a registration date is treated as having no tenure.
390	     */
391	    private long tenureFiscalYears(Owner owner) {
392	        LocalDate registrationDate = owner.getRegistrationDate();
393	        if (registrationDate == null) {
394	            return 0;
395	        }
396	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
397	    }
398	
399	    /**
400	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
401	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
402	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
403	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
404	     * owner has no registration date.
405	     */
406	    protected Boolean bulkSignupWarning(Owner owner) {
407	        LocalDate registrationDate = owner.getRegistrationDate();
408	        if (registrationDate == null) {
409	            return false;
410	        }
411	        long othersOnDay = this.clinicService.findAllOwners().stream()
412	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
413	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
414	            .count();
415	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
416	    }
417	
418	    /**
419	     * Flags a city approaching its hard capacity limit: {@code true} when this owner's city already
420	     * holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one owners,
421	     * inclusive (excluding the owner itself), so on a create the flag reflects the owners that
422	     * pre-existed it in that city, matching the count the per-city capacity limit is enforced
423	     * against. Cities are compared case-insensitively, as they are for the capacity limit. Returns
424	     * {@code false} when the owner has no city.
425	     */
426	    protected Boolean capacityWarning(Owner owner) {
427	        String city = owner.getCity();
428	        if (city == null) {
429	            return false;
430	        }
431	        long othersInCity = this.clinicService.findAllOwners().stream()
432	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
433	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
434	            .count();
435	        return othersInCity >= CAPACITY_WARNING_THRESHOLD && othersInCity < CITY_CAPACITY;
436	    }
437	
438	    /**
439	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
440	     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
441	     * {@code null} when no customer code has been assigned.
442	     */
443	    protected Integer checkDigit(Owner owner) {
444	        String customerCode = owner.getCustomerCode();
445	        if (customerCode == null) {
446	            return null;
447	        }
448	        int sum = 0;
449	        boolean dbl = true;
450	        for (int i = customerCode.length() - 1; i >= 0; i--) {
451	            char c = customerCode.charAt(i);
452	            if (c < '0' || c > '9') {
453	                continue;
454	            }
455	            int d = c - '0';
456	            if (dbl) {
457	                d *= 2;
458	                if (d > 9) {
459	                    d -= 9;
460	                }
461	            }
462	            sum += d;
463	            dbl = !dbl;
464	        }
465	        return (10 - (sum % 10)) % 10;
466	    }
467	
468	    /**
469	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
470	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
471	     * title was supplied (a {@code null} or blank title).
472	     */
473	    protected String salutation(Owner owner) {
474	        String title = owner.getTitle();
475	        String lastName = owner.getLastName();
476	        if (title == null || title.isBlank()) {
477	            return lastName;
478	        }
479	        return title + " " + lastName;
480	    }
481	
482	    /**
483	     * Derives the owner's {@code selfLink}: the canonical link to this owner resource, formatted
484	     * {@code /api/owners/<id>} using the owner's id. Returns {@code null} when the owner has no id.
485	     */
486	    protected String selfLink(Owner owner) {
487	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
488	    }
489	
490	    public abstract Owner toOwner(OwnerDto ownerDto);
491	
492	    @Mapping(target = "id", ignore = true)
493	    @Mapping(target = "pets", ignore = true)
494	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
495	
496	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
497	
498	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
499	
500	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
501	        OwnerPageDto ownerPageDto = new OwnerPageDto();
502	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
503	        ownerPageDto.setPage(ownerPage.getNumber());
504	        ownerPageDto.setSize(ownerPage.getSize());
505	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
506	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
507	        return ownerPageDto;
508	    }
509	}
