 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /**
     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
     */
    private static final Pattern EMAIL_PATTERN =
        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    /**
     * Email domains rejected as disposable/throwaway addresses. An owner whose email domain matches
     * one of these (compared case-insensitively) is rejected with 400.
     */
    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    /**
     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
     * new owner's id, memberId, registrationDate and membershipLevel, followed by an immutable
     * structured {@link OwnerCreatedEvent} serialized as JSON.
     */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /**
     * Source of the {@code seq} carried by each {@link OwnerCreatedEvent}: a monotonically increasing
     * integer allocated once per successful owner create, so the structured events form an ordered,
     * gap-free sequence within the running application.
     */
    private static final AtomicLong AUDIT_EVENT_SEQUENCE = new AtomicLong();

    /**
     * Common street-type abbreviations expanded during address normalization, keyed by the
     * upper-cased abbreviation.
     */
    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    /**
     * Maximum number of owners a single city may contain. A create is rejected once the owner's
     * city already holds this many owners.
     */
    private static final int CITY_CAPACITY = 50;

    /**
     * Maximum number of owners that may be created on a single day. A create is rejected once this
     * many owners already carry the current day as their {@code registrationDate}.
     */
    private static final int DAILY_OWNER_LIMIT = 100;

    /**
     * Fixed public holidays that the business-day roll skips: when an adjusted registration date lands
     * on one of these it advances to the next non-holiday business day.
     */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    /**
     * Remembers the id of the owner created under each seen {@code Idempotency-Key}, so a create that
     * repeats with an already-seen key returns the originally created owner instead of creating a
     * duplicate.
     */
    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        String idempotencyKey = currentIdempotencyKey();
        if (idempotencyKey != null) {
            Integer existingId = ownersByIdempotencyKey.get(idempotencyKey);
            if (existingId != null) {
                Owner existing = this.clinicService.findOwnerById(existingId);
                if (existing != null) {
                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
                }
            }
        }
        validateRequiredFields(ownerFieldsDto);
        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        applyAddress(owner, ownerFieldsDto);
        rejectFutureRegistrationDate(owner.getRegistrationDate());
        LocalDate effectiveDate = owner.getRegistrationDate() == null
            ? LocalDate.now()
            : owner.getRegistrationDate();
        owner.setRegistrationDate(toBusinessDay(effectiveDate));
        rejectWhenDailyLimitReached(owner.getRegistrationDate());
        rejectWhenCityAtCapacity(owner.getCity());
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        applyHousehold(owner);
        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        rejectDuplicateIdentity(owner);
        owner.setMemberId(memberId(owner));
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
        flagPossibleDuplicate(owner, sharesHousehold);
        this.clinicService.saveOwner(owner);
        if (idempotencyKey != null) {
            ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
        }
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            ownerDto.getMembershipLevel());
        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
        AUDIT.info("{}", event.toJson());
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * Reads the {@code Idempotency-Key} header of the request currently being handled, returning
     * {@code null} when the header is absent or blank (or there is no bound request). A non-blank
     * value opts the create into idempotent replay via {@link #ownersByIdempotencyKey}.
     *
     * @return the trimmed idempotency key, or {@code null} when none was supplied
     */
    private String currentIdempotencyKey() {
        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
            return null;
        }
        String key = attrs.getRequest().getHeader("Idempotency-Key");
        return isBlank(key) ? null : key.trim();
    }

    /**
     * Returns the owner's current primary identifier, the value carried by the {@link OwnerCreatedEvent}
     * so downstream consumers can key the create off the owner's canonical identity. An owner's primary
     * identifier is its unified {@code memberId}, and the emitted event follows automatically.
     *
     * @param owner the freshly created owner, with its identifiers already assigned
     * @return the owner's current primary identifier
     */
    private String primaryIdentifier(Owner owner) {
        return owner.getMemberId();
    }

    /**
     * Builds the owner's unified member id, formatted {@code <REGION><FY><HASH8><CHK>}: REGION is the
     * region code derived from the owner's postcode (falling back to the city-to-region table, then
     * {@code UNKNOWN}); FY is the 2-digit fiscal year of the owner's business-day-adjusted registration
     * date; HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the owner's normalized
     * telephone concatenated with its last name; and CHK is a single Luhn check digit computed over the
     * digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D3}).
     *
     * <p>Should the computed member id collide with an existing owner's {@code memberId}, it is
     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
     * unique (e.g. {@code NSW261A2B3C4D3-2}), so distinct owners always receive distinct member ids.
     *
     * @param owner the owner being created, with its normalized telephone and business-day-adjusted
     *              registration date already applied
     * @return the assigned, de-duplicated member id
     */
    private String memberId(Owner owner) {
        String core = regionCode(owner)
            + String.format("%02d", fiscalYear(owner.getRegistrationDate()) % 100)
            + identityHash8(owner.getTelephone(), owner.getLastName());
        String base = core + luhnCheckDigit(core);
        Set<String> existingIds = this.clinicService.findAllOwners().stream()
            .map(Owner::getMemberId)
            .filter(id -> id != null)
            .collect(java.util.stream.Collectors.toSet());
        if (!existingIds.contains(base)) {
            return base;
        }
        int n = 2;
        while (existingIds.contains(base + "-" + n)) {
            n++;
        }
        return base + "-" + n;
    }

    /**
     * Computes the Luhn check digit (a single digit 0-9) over the digits contained in the given value.
     * Non-digit characters are ignored.
     *
     * @param value the value whose digits the check digit is computed over
     * @return the Luhn check digit
     */
    private int luhnCheckDigit(String value) {
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
     * postcode nor the city identifies a region.
     *
     * @param owner the owner being created
     * @return the derived region code, never {@code null}
     */
    private String regionCode(Owner owner) {
        String fromPostcode = regionFromPostcode(owner.getPostcode());
        if (fromPostcode != null) {
            return fromPostcode;
        }
        String fromCity = region(owner.getCity());
        return fromCity == null ? "UNKNOWN" : fromCity;
    }

    /**
     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
     * postcode is absent, not 4 digits, or in no known range.
     *
     * @param postcode the owner's postcode, may be {@code null}
     * @return the region code, or {@code null} when no known range contains the postcode
     */
    private String regionFromPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
     *
     * @param telephone the owner's normalized (E.164) telephone
     * @param lastName  the owner's last name
     * @return the 8-character upper-cased hex hash
     */
    private String identityHash8(String telephone, String lastName) {
        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /**
     * The month the fiscal year starts on (1 July).
     */
    private static final int FISCAL_YEAR_START_MONTH = 7;

    /**
     * Derives the fiscal year of the given date. The fiscal year starts on 1 July, so a date on or
     * after 1 July belongs to the following calendar year's fiscal year (e.g. 2026-07-01 is fiscal
     * year 2027) while an earlier date takes the calendar year unchanged.
     *
     * @param date the date to derive the fiscal year of
     * @return the fiscal year
     */
    private int fiscalYear(LocalDate date) {
        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
    }

    /**
     * Counts the existing owners that already share the given firstName and lastName, compared
     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
     * the owners that pre-existed this create.
     *
     * @param firstName the new owner's first name
     * @param lastName  the new owner's last name
     * @return the number of existing namesakes
     */
    private int countNamesakes(String firstName, String lastName) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
                && equalsIgnoreCase(existing.getLastName(), lastName))
            .count();
    }

    /**
     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
     * still resemble an existing owner: when it shares an existing owner's {@code soundex(lastName)}
     * and postcode while deriving a different identityKey, the owner is flagged with
     * {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing owner's id.
     * When no such owner exists the flag is set to {@code false} and no match id is recorded. An
     * owner with no postcode can never soft-match and is always {@code false}.
     *
     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
     * always flagged {@code false}.
     *
     * @param owner           the owner being created, with its normalized telephone already applied
     * @param sharesHousehold whether the request declared it shares a household; a declared member is
     *                        never flagged as a possible duplicate
     */
    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        } else {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
        }
    }

    /**
     * Finds the existing owner this owner soft-matches: a different {@link #identityKey(Owner)
     * identityKey} but the same {@code soundex(lastName)} and the same postcode. Because the
     * telephone now feeds the identityKey, two owners sharing a lastName and postcode with different
     * telephones have different keys and so soft-match here rather than being rejected as a hard
     * duplicate. When several existing owners match, the one with the lowest id is chosen so the
     * result is deterministic. Returns {@code null} when the owner has no postcode or no such
     * existing owner exists.
     *
     * @param owner the owner being created
     * @return the matching existing owner, or {@code null} when there is no soft-match
     */
    private Owner findPossibleDuplicate(Owner owner) {
        if (isBlank(owner.getPostcode())) {
            return null;
        }
        String identityKey = identityKey(owner);
        String soundex = IdentityKeys.soundex(owner.getLastName());
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !identityKey.equals(identityKey(existing))
                && soundex.equals(IdentityKeys.soundex(existing.getLastName()))
                && owner.getPostcode().equals(existing.getPostcode()))
            .min(Comparator.comparing(Owner::getId))
            .orElse(null);
    }

    /**
     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
     * customer-code sequence is derived.
     *
     * @param city the new owner's city
     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
     */
    private void rejectWhenCityAtCapacity(String city) {
        long count = this.clinicService.findAllOwners().stream()
            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
            .count();
        if (count >= CITY_CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }

    /**
     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
     * business-day registration date, so the limit is enforced per business day and weekend
     * requests count against the Monday they roll forward to.
     *
     * @param registrationDate the owner's adjusted (business-day) registration date
     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
     *                                  registration date
     */
    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
        long count = this.clinicService.findAllOwners().stream()
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
        if (count >= DAILY_OWNER_LIMIT) {
            throw new DailyOwnerLimitException(registrationDate);
        }
    }

    /**
     * Rejects creating an owner whose supplied {@code registrationDate} lies in the future, i.e. is
     * later than the current server date. A {@code null} registration date is accepted (it defaults
     * to the server date) and today or any past date is allowed; only a future value is rejected.
     *
     * @param registrationDate the registration date supplied on the request, may be {@code null}
     * @throws FutureRegistrationDateException if the supplied date is later than the server date
     */
    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(registrationDate);
        }
    }

    /**
     * Rolls a registration date forward onto a business day: while it falls on a Saturday, a Sunday or
     * a listed {@link #PUBLIC_HOLIDAYS public holiday} it advances one day at a time until it lands on
     * a non-holiday weekday, otherwise it is returned unchanged. Applied to the effective registration
     * date (whether supplied in the request or defaulted to the server date) so a weekend or holiday
     * value never persists as an owner's {@code registrationDate}.
     *
     * @param date the effective registration date
     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
     */
    private LocalDate toBusinessDay(LocalDate date) {
        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
            || date.getDayOfWeek() == DayOfWeek.SUNDAY
            || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }

    /**
     * Whether an existing owner has been soft-deleted. A soft-deleted owner retains its row but is
     * ignored by the create endpoint's duplicate and identity checks, so a normally-blocking match
     * against a deleted owner is allowed.
     *
     * @param owner an existing owner
     * @return {@code true} when the owner is flagged deleted
     */
    private boolean isDeleted(Owner owner) {
        return Boolean.TRUE.equals(owner.getDeleted());
    }

    /**
     * Rejects an owner whose required fields are missing or blank. Collects the names of every
     * offending field so the client learns about all of them at once.
     *
     * <p>An address may be supplied in either form: the structured {@code addressLine1} or the flat
     * {@code address}. The {@code address} error is raised only when both are missing or blank, so a
     * structured owner (with {@code addressLine1}) and an earlier flat owner (with {@code address})
     * are both accepted.
     *
     * @param ownerFieldsDto the submitted owner fields
     * @throws MissingOwnerFieldsException if firstName, lastName, address (in either form), city or
     *                                     telephone is missing or blank
     */
    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
        List<String> errors = new ArrayList<>();
        if (isBlank(ownerFieldsDto.getFirstName())) {
            errors.add("firstName");
        }
        if (isBlank(ownerFieldsDto.getLastName())) {
            errors.add("lastName");
        }
        if (isBlank(normalizeAddress(ownerFieldsDto.getAddressLine1()))
            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
            errors.add("address");
        }
        if (isBlank(ownerFieldsDto.getCity())) {
            errors.add("city");
        }
        if (isBlank(ownerFieldsDto.getTelephone())) {
            errors.add("telephone");
        }
        if (!errors.isEmpty()) {
            throw new MissingOwnerFieldsException(errors);
        }
    }

    private boolean isBlank(String value) {
        return value == null || value.isBlank();
    }

    /**
     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
     */
    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
     * is optional and accepted, keeping the create contract backward-compatible. When present the
     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
     *
     * @param postcode the raw postcode value as submitted, may be {@code null}
     * @param city     the owner's city, used to resolve the region whose range applies
     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
     *                                  the city's region
     */
    private void validatePostcode(String postcode, String city) {
        if (isBlank(postcode)) {
            return;
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException(postcode, city);
        }
        String region = region(city);
        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
        if (range != null) {
            int value = Integer.parseInt(postcode);
            if (value < range[0] || value > range[1]) {
                throw new InvalidPostcodeException(postcode, city);
            }
        }
    }

    /**
     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
     *
     * @param city the owner's city
     * @return the region code, or {@code null} when the city has no known region
     */
    private String region(String city) {
        if (city == null) {
            return null;
        }
        return switch (city) {
            case "Sydney" -> "NSW";
            case "Melbourne" -> "VIC";
            case "Brisbane" -> "QLD";
            default -> null;
        };
    }

    /**
     * The number of national (subscriber) digits an E.164 number must carry for a given country
     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
     * national digits and the North American Numbering Plan ('+1') requires 10.
     */
    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
        Map.of("61", 9, "1", 10);

    /**
     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
     * followed by 8 to 15 digits, and its national-number length must match the one required by its
     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
     *
     * @param telephone the raw telephone value as submitted
     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
     *                                   national-number length is wrong for its country code
     */
    private String normalizeTelephone(String telephone) {
        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
        String nationalSignificantNumber;
        if (cleaned.startsWith("+")) {
            nationalSignificantNumber = cleaned.substring(1);
        } else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            nationalSignificantNumber = "61" + national;
        }
        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
            throw new InvalidTelephoneException(telephone);
        }
        validateNationalNumberLength(nationalSignificantNumber, telephone);
        return "+" + nationalSignificantNumber;
    }

    /**
     * Validates the national-number length of an E.164 number against its country calling code. The
     * significant number is a country code immediately followed by the national digits; for each
     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
     * left unchecked.
     *
     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
     * @param rejectedValue             the raw telephone value, reported on rejection
     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
     */
    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
            String countryCode = rule.getKey();
            if (nationalSignificantNumber.startsWith(countryCode)) {
                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
                if (nationalDigits != rule.getValue()) {
                    throw new InvalidTelephoneException(rejectedValue);
                }
                return;
            }
        }
    }

    /**
     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
     * value is treated as absent and returns {@code null}); when present the value must be a
     * syntactically valid address, and is stored and returned lower-cased.
     *
     * @param email the raw email value as submitted, may be {@code null}
     * @return the lower-cased email, or {@code null} when none was supplied
     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
     */
    private String normalizeEmail(String email) {
        if (email == null || email.isBlank()) {
            return null;
        }
        String normalized = email.trim().toLowerCase();
        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
            throw new InvalidEmailException(email);
        }
        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
            throw new DisposableEmailException(email);
        }
        return normalized;
    }

    /**
     * The single, consolidated duplicate check. Rejects the owner being created when its whole
     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing, non-deleted owner.
     * Because the key is the SHA-256 of the normalized telephone, lower-cased email and
     * {@code soundex(lastName)} joined together, this one check is the sole duplicate rule: only an
     * exact full-key match counts as a duplicate, so two owners sharing a lastName and postcode but
     * carrying different telephones have different keys and are both allowed (the second is instead
     * flagged a soft match).
     *
     * @param owner the owner being created, with its normalized telephone and email already applied
     * @throws DuplicateIdentityException if another owner already has the same identityKey
     */
    private void rejectDuplicateIdentity(Owner owner) {
        String identityKey = identityKey(owner);
        boolean inUse = this.clinicService.findAllOwners().stream()
            .filter(existing -> !isDeleted(existing))
            .map(this::identityKey)
            .anyMatch(identityKey::equals);
        if (inUse) {
            throw new DuplicateIdentityException(identityKey);
        }
    }

    /**
     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 of
     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A {@code null}
     * telephone or email contributes an empty segment. Every duplicate decision is made by comparing
     * whole identityKeys.
     *
     * @param owner the owner whose identityKey to derive
     * @return the derived identityKey
     */
    private String identityKey(Owner owner) {
        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
    }

    /**
     * Applies the household rule to an owner being created. The household is keyed on
     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
     * and postcode automatically share the identifier — the link is computed, not created by a flag.
     *
     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
     * same householdId is a member of the same household. A new owner sharing an existing household
     * is admitted as a further member of it — its membership level is then capped by the household
     * (see {@code OwnerMapper#membershipLevel}) rather than the create being rejected.
     *
     * @param owner the owner being created
     */
    private void applyHousehold(Owner owner) {
        owner.setHouseholdId(householdId(owner));
    }

    /**
     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
     * creation order. A {@code null} postcode contributes an empty segment.
     *
     * @param owner the owner whose household identifier to derive
     * @return the household identifier
     */
    private String householdId(Owner owner) {
        String lastNameKey = toHouseholdKey(owner.getLastName());
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /**
     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
     * string.
     */
    private String toHouseholdKey(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Applies the owner's address, preferring the structured form over the flat one. The structured
     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
     * address therefore sees the structured value when present, falling back to the flat one.
     *
     * @param owner the owner being created
     * @param dto   the submitted owner fields
     */
    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
        String line1 = normalizeAddress(dto.getAddressLine1());
        String line2 = normalizeAddress(dto.getAddressLine2());
        String flat = normalizeAddress(dto.getAddress());
        String effectiveLine1 = line1.isEmpty() ? flat : line1;
        String effectiveLine2 = line1.isEmpty() ? "" : line2;
        String composed = effectiveLine2.isEmpty()
            ? effectiveLine1
            : effectiveLine1 + " " + effectiveLine2;
        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
        owner.setAddress(composed);
    }

    /**
     * Normalizes a submitted address into the canonical form stored and returned for an owner:
     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
     * value, or one that is blank once trimmed, normalizes to an empty string.
     *
     * @param address the raw address value as submitted, may be {@code null}
     * @return the normalized address, or an empty string when none was supplied
     */
    private String normalizeAddress(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder normalized = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                normalized.append(' ');
            }
            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return normalized.toString();
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        owner.setDeleted(true);
        this.clinicService.saveOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * Immutable structured audit event emitted alongside the human-readable audit line on a successful
     * owner create. It records the create's monotonic {@code seq}, the new owner's id, the owner's
     * current primary identifier and its membership level, plus a fixed {@code OWNER_CREATED} marker.
     *
     * <p>The primary identifier is serialized under the {@code customerCode} key, matching the owner's
     * present-day primary identifier. When the customer code is later unified into the member id the
     * event simply carries the member id value in its place.
     */
    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
                                     Integer membershipLevel) {

        private static final String EVENT = "OWNER_CREATED";

        /**
         * Renders the event as a compact JSON object
         * {@code {"seq":..,"ownerId":..,"customerCode":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
         */
        String toJson() {
            StringBuilder json = new StringBuilder(96);
            json.append('{')
                .append("\"seq\":").append(this.seq)
                .append(",\"ownerId\":").append(this.ownerId)
                .append(",\"customerCode\":").append(jsonString(this.customerCode))
                .append(",\"membershipLevel\":").append(this.membershipLevel)
                .append(",\"event\":").append(jsonString(EVENT))
                .append('}');
            return json.toString();
        }

        /**
         * Renders a nullable string as a JSON literal: {@code null} when absent, otherwise a
         * double-quoted, minimally-escaped string.
         */
        private static String jsonString(String value) {
            if (value == null) {
                return "null";
            }
            StringBuilder out = new StringBuilder(value.length() + 2);
            out.append('"');
            for (int i = 0; i < value.length(); i++) {
                char c = value.charAt(i);
                switch (c) {
                    case '"' -> out.append("\\\"");
                    case '\\' -> out.append("\\\\");
                    case '\n' -> out.append("\\n");
                    case '\r' -> out.append("\\r");
                    case '\t' -> out.append("\\t");
                    default -> {
                        if (c < 0x20) {
                            out.append(String.format("\\u%04x", (int) c));
                        } else {
                            out.append(c);
                        }
                    }
                }
            }
            out.append('"');
            return out.toString();
        }
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.samples.petclinic.util.IdentityKeys;

import java.time.LocalDate;
import java.time.Period;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalInt;
import java.util.stream.Stream;

/**
 * Maps Owner &amp; OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public abstract class OwnerMapper {

    /**
     * A create is flagged with {@code bulkSignupWarning=true} once more than this many owners have
     * already been created on the same registration date.
     */
    private static final int BULK_SIGNUP_THRESHOLD = 80;

    /**
     * A create is flagged with {@code capacityWarning=true} when its city already holds at least
     * this many owners (excluding the owner itself), approaching the hard capacity limit.
     */
    private static final int CAPACITY_WARNING_THRESHOLD = 40;

    /**
     * The hard per-city capacity limit; at or above it a create is rejected rather than warned, so
     * the warning window is {@code [CAPACITY_WARNING_THRESHOLD, CITY_CAPACITY)}.
     */
    private static final int CITY_CAPACITY = 50;

    @Autowired
    protected ClinicService clinicService;

    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
    @Mapping(target = "salutation", expression = "java(salutation(owner))")
    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "timezone", expression = "java(timezone(owner))")
    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
    @Mapping(target = "capacityWarning", expression = "java(capacityWarning(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
    public abstract OwnerDto toOwnerDto(Owner owner);

    /**
     * The month the fiscal year starts on (1 July).
     */
    private static final int FISCAL_YEAR_START_MONTH = 7;

    /**
     * Derives the fiscal year (as an integer) of the given date. The fiscal year starts on 1 July,
     * so a date on or after 1 July belongs to the following calendar year's fiscal year (e.g.
     * 2026-07-01 is fiscal year 2027) while an earlier date takes the calendar year unchanged.
     */
    private int fiscalYearOf(LocalDate date) {
        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
    }

    /**
     * Derives the owner's {@code fiscalYear}, formatted {@code FY<YY>} where YY is the last two
     * digits of the fiscal year (starting 1 July) of the owner's business-day-adjusted
     * {@code registrationDate}. Returns {@code null} when no registration date is present.
     */
    protected String fiscalYear(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return null;
        }
        return String.format("FY%02d", fiscalYearOf(registrationDate) % 100);
    }

    /**
     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
     * the registration date (against which the age is measured) is absent.
     */
    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
        LocalDate birthDate = owner.getBirthDate();
        LocalDate registrationDate = owner.getRegistrationDate();
        if (birthDate == null || registrationDate == null) {
            return null;
        }
        int age = Period.between(birthDate, registrationDate).getYears();
        if (age < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
        if (age < 65) {
            return OwnerDto.AgeBandEnum.ADULT;
        }
        return OwnerDto.AgeBandEnum.SENIOR;
    }

    /**
     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
     * longest first so the correct code is matched before a shorter prefix of it. Australia
     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
     * endpoint normalizes against.
     */
    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");

    /**
     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
     * humans as the country code, a space, then the national digits grouped in threes (e.g.
     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
     */
    protected String telephoneDisplay(Owner owner) {
        String telephone = owner.getTelephone();
        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
            return telephone;
        }
        String digits = telephone.substring(1);
        String countryCode = KNOWN_COUNTRY_CODES.stream()
            .filter(digits::startsWith)
            .findFirst()
            .orElse("");
        String national = digits.substring(countryCode.length());
        StringBuilder grouped = new StringBuilder();
        for (int i = 0; i < national.length(); i++) {
            if (i > 0 && i % 3 == 0) {
                grouped.append(' ');
            }
            grouped.append(national.charAt(i));
        }
        return "+" + countryCode + " " + grouped;
    }

    /**
     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key: the
     * lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
     * soundex(lastName)}. A {@code null} telephone or email contributes an empty segment.
     */
    protected String identityKey(Owner owner) {
        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
    }

    /**
     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
     * present, otherwise {@code PHONE}.
     */
    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
    }

    /**
     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
     */
    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
     * moves in lockstep with the identity assigned on create. When no customer code has been
     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
     */
    protected String locality(Owner owner) {
        String customerCode = owner.getCustomerCode();
        if (customerCode != null) {
            int dash = customerCode.indexOf('-');
            if (dash > 0) {
                return customerCode.substring(0, dash);
            }
        }
        String fromPostcode = regionFromPostcode(owner.getPostcode());
        if (fromPostcode != null) {
            return fromPostcode;
        }
        String city = owner.getCity();
        if (city == null) {
            return "UNKNOWN";
        }
        return switch (city) {
            case "Sydney" -> "NSW";
            case "Melbourne" -> "VIC";
            case "Brisbane" -> "QLD";
            default -> "UNKNOWN";
        };
    }

    /**
     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
     */
    private static final Map<String, String> REGION_TIMEZONE = Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    /**
     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
     */
    protected String timezone(Owner owner) {
        return REGION_TIMEZONE.get(locality(owner));
    }

    /**
     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
     * the postcode is absent, not 4 digits, or in no known range.
     */
    private String regionFromPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The minimum {@link #membershipLevel(Owner) membership level} at which an owner is a
     * {@code PREMIUM} tier for {@link #ownerSegment(Owner) segmentation}; below it the owner is
     * {@code STANDARD}.
     */
    private static final int PREMIUM_TIER_MIN_LEVEL = 3;

    /**
     * The regions treated as {@code METRO} for {@link #ownerSegment(Owner) segmentation}; any other
     * locality (e.g. {@code UNKNOWN}) is {@code REGIONAL}.
     */
    private static final java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");

    /**
     * Derives the owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} (one of
     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
     * {@code STANDARD_REGIONAL}). TIER is {@code PREMIUM} when the owner's
     * {@link #membershipLevel(Owner) membership level} is {@value #PREMIUM_TIER_MIN_LEVEL} or more,
     * otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
     * {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
     * {@code REGIONAL}.
     */
    protected OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
        String tier = membershipLevel(owner) >= PREMIUM_TIER_MIN_LEVEL ? "PREMIUM" : "STANDARD";
        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
    }

    /**
     * The minimum household size (counting the owner itself) that earns household membership
     * points.
     */
    private static final int HOUSEHOLD_POINTS_SIZE = 3;

    /**
     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
     * clears this threshold.
     */
    private static final int TENURE_POINTS_FISCAL_YEARS = 1;

    /**
     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
     */
    protected Integer membershipPoints(Owner owner) {
        int points = 0;
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        if (hasEmail) {
            points += 2;
        }
        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        if (noNamesakes) {
            points += 1;
        }
        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
            points += 2;
        }
        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
            points += 3;
        }
        return points;
    }

    /**
     * Derives the owner's membership level, capped by their household. The level starts from the
     * owner's own {@link #uncappedMembershipLevel(Owner) points-based level} but may not exceed one
     * above the current maximum level among the owner's existing household members (other owners
     * sharing its {@code householdId}). When the owner has no existing household member no cap
     * applies and the points-based level is returned unchanged.
     */
    protected Integer membershipLevel(Owner owner) {
        int level = uncappedMembershipLevel(owner);
        OptionalInt maxHouseholdLevel = otherHouseholdMembers(owner)
            .mapToInt(this::uncappedMembershipLevel)
            .max();
        if (maxHouseholdLevel.isEmpty()) {
            return level;
        }
        return Math.min(level, maxHouseholdLevel.getAsInt() + 1);
    }

    /**
     * The owner's points-based membership level, before the household ceiling is applied: level 1
     * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more (see
     * {@link #membershipPoints(Owner) membership points}). The household members' maximum against
     * which {@link #membershipLevel(Owner)} caps is measured with this uncapped value, so mutual
     * household members do not recurse into each other's caps.
     */
    private int uncappedMembershipLevel(Owner owner) {
        int points = membershipPoints(owner);
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * The owner's existing household members: every other owner (excluding the owner itself) sharing
     * its {@code householdId}. Empty when the owner has no household identifier or is the sole member
     * of its household.
     */
    private Stream<Owner> otherHouseholdMembers(Owner owner) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return Stream.empty();
        }
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()));
    }

    /**
     * The number of owners in this owner's household — the count of owners (including this one)
     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
     */
    private long householdSize(Owner owner) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return 0;
        }
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .count();
    }

    /**
     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
     * owner without a registration date is treated as having no tenure.
     */
    private long tenureFiscalYears(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return 0;
        }
        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
    }

    /**
     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
     * owner has no registration date.
     */
    protected Boolean bulkSignupWarning(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return false;
        }
        long othersOnDay = this.clinicService.findAllOwners().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
        return othersOnDay > BULK_SIGNUP_THRESHOLD;
    }

    /**
     * Flags a city approaching its hard capacity limit: {@code true} when this owner's city already
     * holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one owners,
     * inclusive (excluding the owner itself), so on a create the flag reflects the owners that
     * pre-existed it in that city, matching the count the per-city capacity limit is enforced
     * against. Cities are compared case-insensitively, as they are for the capacity limit. Returns
     * {@code false} when the owner has no city.
     */
    protected Boolean capacityWarning(Owner owner) {
        String city = owner.getCity();
        if (city == null) {
            return false;
        }
        long othersInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
            .count();
        return othersInCity >= CAPACITY_WARNING_THRESHOLD && othersInCity < CITY_CAPACITY;
    }

    /**
     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
     * {@code null} when no customer code has been assigned.
     */
    protected Integer checkDigit(Owner owner) {
        String customerCode = owner.getCustomerCode();
        if (customerCode == null) {
            return null;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = customerCode.length() - 1; i >= 0; i--) {
            char c = customerCode.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
     * title was supplied (a {@code null} or blank title).
     */
    protected String salutation(Owner owner) {
        String title = owner.getTitle();
        String lastName = owner.getLastName();
        if (title == null || title.isBlank()) {
            return lastName;
        }
        return title + " " + lastName;
    }

    /**
     * Derives the owner's {@code selfLink}: the canonical link to this owner resource, formatted
     * {@code /api/owners/<id>} using the owner's id. Returns {@code null} when the owner has no id.
     */
    protected String selfLink(Owner owner) {
        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
    }

    public abstract Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    public abstract Owner toOwner(OwnerFieldsDto ownerDto);

    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

